<?php require_once dirname(__DIR__,2).'/bootstrap.php';$kind=$_GET['kind']??'';$id=(int)($_GET['id']??0);v17_content($kind,$id,current_user());if(!in_array($kind,['clip','post'],true))json_response(['message'=>'Geçersiz tür.'],400);$table=$kind==='clip'?'clip_likes':'feed_post_likes';$col=$kind==='clip'?'clip_id':'post_id';$before=(int)($_GET['before_id']??PHP_INT_MAX);$rows=v17_query("SELECT u.* FROM $table l JOIN users u ON u.id=l.user_id WHERE l.$col=? AND u.id<? ORDER BY u.id DESC LIMIT 51",[$id,$before])->fetchAll();$more=count($rows)>50;$rows=array_slice($rows,0,50);json_response(['people'=>array_map('v17_person',$rows),'nextBeforeId'=>$more?(int)end($rows)['id']:null]);